import type { CheckStatus, InventoryItem, ItemType, Placement, Quantity, PageRegion } from "../../lib/types.ts";
import references from "./references.json" with { type: "json" };

interface Extra {
  quantity?: Quantity;
  status?: CheckStatus;
  note?: string;
  label?: string;
  region?: PageRegion;
}

function i(
  id: string,
  type: ItemType,
  title: string,
  statement: string,
  page: number,
  section: string,
  quote: string | undefined,
  place: Placement,
  extra: Extra = {},
): InventoryItem {
  return {
    id,
    type,
    title,
    statement,
    quantity: extra.quantity,
    source: { page, section, quote, label: extra.label, region: extra.region },
    place,
    status: extra.status ?? "verified",
    note: extra.note,
  };
}

